function initCarousel(root) {
  var items = Array.prototype.slice.call(root.querySelectorAll('.carousel-item'));
  if (!items.length) return;
  var indicators = Array.prototype.slice.call(root.querySelectorAll('.carousel-indicators [data-bs-slide-to]'));
  var interval = parseInt(root.getAttribute('data-bs-interval'), 10) || 5000;
  var index = items.findIndex(i => i.classList.contains('active'));
  if (index < 0) index = 0;
  var timer = null
};

function show(next) {
  next = (next + items.length) % items.length;
  items[index].classList.remove('active');
  items[next].classList.add('active');
  indicators.forEach(function (ind, i) {
    ind.classList.toggle('active', i === next);
    ind.setAttribute('aria-current', i === next ? 'true' : 'false');
  });
  index = next;
};

function start() {
  stop();
  if (root.getAttribute('data-bs-ride') === 'false') return;
  timer = setInterval(function () { show(index + 1); }, interval);
}

function stop() {
  if (timer) clearInterval(timer);
  timer = null;
}

root.querySelectorAll('[data-bs-slide]').forEach(function (btn) {
  btn.addEventListener('click', function (e) {
    e.preventDefault();
    show(index + (btn.getAttribute('data-bs-slide') === 'prev' ? -1 : 1));
    start();
  });
});
indicators.forEach(function (ind, i) {
  ind.addEventListener('click', function (e) { e.preventDefault(); show(i); start(); });
});